const topic = $json.topic || '';
let payload = {};
try { payload = typeof $json.payload === 'string' ? JSON.parse($json.payload) : ($json.payload || {}); } catch (e) {}
// slug = everything between 'zenbo/' and '/status/'
const parts = topic.split('/');
const slug = parts.length >= 4 ? parts.slice(1, -2).join('/') : 'unknown';
const kind = parts[parts.length - 1] || 'status';
return [{ json: {
  robot_slug: payload.robot_slug || slug,
  kind,
  client_ip: payload.client_ip || payload.ip || null,
  version_name: payload.version_name || payload.app || null,
  state: payload.state || null,
  error_code: payload.code || null,
  ts: new Date().toISOString()
} }];

const n = $input.all()[0].json;
return [{ json: {
  notify: true,
  text: `${n.robot_slug} ${n.state === 'connected' ? '🟢 เชื่อมต่อแล้ว' : '🔴 หลุดการเชื่อมต่อ'} · ${n.client_ip || 'no IP'} · ${n.version_name || ''}`,
  robot_slug: n.robot_slug
} }];

const n = $input.all()[0].json;
const relevant = ['vision', 'error', 'action_done', 'robot_state'];
return [{ json: {
  notify: relevant.includes(n.kind),
  text: `${n.robot_slug} · ${n.kind}: ${JSON.stringify(n)}`,
  robot_slug: n.robot_slug
} }];
